class EaseGraph {
	// Draws a fade circle using the ease method.
	// Requires the p5.func library.

	// Before calling draw():
	//   stroke() to set axis color.
	//   translate to top left.

	// ease_method: string from p5.Ease methods (	"linear", "quadraticIn", "quadraticOut", "quadraticInOut" ... )
	// steps: time-resolution
	// fade_factor: how fast the points should fade away
	constructor(w, h, ease_method, steps, time, fade_factor, circle_size, circle_col, circle_fade_col) {
		this.w = w
		this.h = h
		this.circle_size = circle_size
		this.circle_col = circle_col
		this.circle_fade_col = circle_fade_col
		this.ease_method = ease_method
		this.ease = new p5.Ease()
		this.circles = []
		this.t = 0
		this.dt = time*1000/steps
		this.next_update = 0
		this.val = 0
		this.step = 1 / steps
		this.fade_factor = this.step*fade_factor
	}

	reset() {
		this.circles = []
		this.t = 0
		this.val = 0
		this.next_update = 0
	}

	update() {
		this.val = this.ease[this.ease_method](this.t)

		if (millis() >= this.next_update) {
			this.t += this.step
			this.next_update += this.dt
		}
		this.t = min(max(this.t, 0), 1)
	}

	draw_axes() {
		line(0, this.h, 0, 0)
		line(0, this.h, this.w, this.h)
	}

	draw_graph() {
		let dt = 0.01
		for (let i = 0; i < 1-dt; i += (Math.max(0.001, Math.abs(dt)) || 1)) {
			// point(i*this.w, (1-this.ease[this.ease_method](i))*this.h)
			line(i*this.w, (1-this.ease[this.ease_method](i))*this.h, (i+dt)*this.w, (1-this.ease[this.ease_method](i+dt))*this.h)
		}
	}

	draw() {
		if (millis() < 200) return

		this.draw_axes()

		this.draw_graph()

		let fade_col
		if (this.circle_fade_col != undefined) {
			fade_col = color(this.circle_fade_col)
		}
		if (this.t < 1) {
			this.circles.push(new FadeCircle(this.t*this.w, (1-this.val)*this.h, this.circle_size, color(this.circle_col), this.fade_factor, fade_col))//color(this.circle_fade_col)))
		}

		for (let c of this.circles) {
			c.draw()
		}

		let n = this.circles.length
		for (let i = n-1; i >= 0; i--) {
			if (this.circles[i].age >= 1) {
				this.circles.splice(i, 1)
			}
		}

		this.update()
	}
}

