	ease_graphs.push( new EaseGraph(300, 200, easing_styles[0], 100, 2, 8, 10, color(219, 140, 22), 0) )
}

let es = 0
let es_next = 0
let switch_count = 0
let wait_time = 0
let draw_step = 0
let step_1_t = 0
let fg_col
let g
let left_pad = 100
const SWITCH_AFTER = 2
function draw() {
	fg_col = color(219, 140, 22)
	if (millis() < 500) {
		return
	}

	background(bg_col)

	translate(10, left_pad)

	fill(fg_col, 20, 20)
	noStroke()
	textAlign(CENTER)
	textSize(14)
	textFont("Verdana")
	text(easing_styles[es_next], ease_graphs[0].w/2, -20)

	stroke(fg_col)
	strokeWeight(2)
	if (draw_step === 0) {
		g = ease_graphs[0]
		g.ease_method = easing_styles[es]
		g.draw()
		if (wait_time === 0 && g.circles.length === 0) {
			if (switch_count < SWITCH_AFTER-1) {
				wait_time = millis() + 1000
			}
			else {
				wait_time = millis()
			}
		}

		if (wait_time > 0 && millis() >= wait_time || mouse_click) {
			wait_time = 0
			g.reset()

			if (switch_count >= SWITCH_AFTER-1 || mouse_click) { 
				switch_count = 0
				es_next = (es + 1) % easing_styles.length
				ease_graphs[1].ease_method = easing_styles[es_next]
				draw_step = 1
				step_1_t = 0
			}
			else {
				switch_count += 1
			}			
		}
	}
	else if (draw_step === 1) {
		// Fade switch
		let c1 = lerpColor(fg_col, bg_col, step_1_t**2)
		let c2 = lerpColor(bg_col, fg_col, -step_1_t*(step_1_t-2))
		stroke(c1)
		ease_graphs[0].draw_graph()
		stroke(fg_col)
		ease_graphs[0].draw_axes()
		stroke(c2)
		ease_graphs[1].draw_graph()
		if (step_1_t >= 1 || mouse_click) {
			es = es_next
			ease_graphs[0].ease_method = easing_styles[es]
			draw_step = 0
		}
		else {
			step_1_t += 0.01
		}
	}

	// Text
	textFont(f2)
	translate(ease_graphs[0].w+150, -110)
	noStroke()
	fill(lerpColor(bg_col, fg_col, ease_graphs[0].val))
	textSize(30)
	let t = "Easing transitions"
	let x_max = 300
	let y_max = left_pad + ease_graphs[0].h/2
	if (draw_step === 0) {
		text(t, 0, ease_graphs[0].val*y_max)
	}
	else {
		text(t, 0, y_max)
	}

	mouse_click = false
}






